package com.taxplatform.startup;

import com.taxplatform.localdemo.StartupAdapter;
import com.taxplatform.safety.SafetyInput.Candidate;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.time.ZoneId;
import java.time.ZoneOffset;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

final class WorkspaceTests {
    private static int passed,generated;
    private WorkspaceTests(){ }
    @FunctionalInterface private interface Test{void run()throws Exception;}
    private static void check(String name,Test test)throws Exception{test.run();passed++;System.out.println("PASS "+name);}
    private static void eq(Object a,Object b){if(!java.util.Objects.equals(a,b))throw new AssertionError("workspace assertion failed");}
    private static void fail(int status,String code,Runnable work){try{work.run();}catch(Workspace.Problem e){eq(e.status,status);eq(e.code,code);return;}throw new AssertionError("rejection missing: "+code);}
    private static Map<String,Object> body(Object... pairs){Map<String,Object> out=new LinkedHashMap<>();for(int i=0;i<pairs.length;i+=2)out.put((String)pairs[i],pairs[i+1]);return out;}
    private static Map<String,Object> cmd(Map<String,Object> row,String op,Object... extras){Map<String,Object> out=body("operation",op,"request_id",Workspace.id(),"expected_revision",row.get("revision"));out.putAll(body(extras));return out;}
    private static String create(Workspace w,String owner){return (String)w.createCase(owner,body("title","Sample case","request_id",Workspace.id())).get("id");}
    private static void edit(Workspace w,String owner,String id,String op,Object... extras){w.edit(owner,id,cmd(w.readCase(owner,id),op,extras));}
    private static final class Time extends Clock {Instant current=Instant.parse("2026-11-01T00:00:00Z");@Override public ZoneId getZone(){return ZoneOffset.UTC;}@Override public Clock withZone(ZoneId ignored){return this;}@Override public Instant instant(){return current;}}
    private static String password(){return "Sample-password-"+Workspace.id();}
    private static String account(Workspace w,String login,String role){return (String)(role.equals("CUSTOMER")?w.register(body("username",login,"display_name","Sample "+login,"password",password())):w.createOperator(login,"Sample "+login,password(),role)).get("id");}
    private static Map<String,Object> price(String plan,String at,long amount){return body("request_id",Workspace.id(),"plan",plan,"amount_paise",amount,"effective_at",at,"label","Test planning price");}
    public static void main(String[] args)throws Exception{
        Path folder=Files.createTempDirectory("startup-workspace-tests-");Path records=folder.resolve("records"),key=folder.resolve("keys/vault.key");Time time=new Time();String owner,other,admin,preparer;Map<String,Object> accountBody=body("username","persist_user","display_name","Sample user","password",password());
        try(VaultStore vault=new VaultStore(records,key)){
            Workspace w=new Workspace(vault,time);owner=(String)w.register(accountBody).get("id");other=account(w,"other_user","CUSTOMER");admin=account(w,"ops_admin","ADMIN");preparer=account(w,"team_staff","PREPARER");
            check("strict JSON rejects duplicates floats malformed UTF8 and invalid surrogates",()->{for(byte[] bytes:List.of("{\"x\":1,\"x\":2}".getBytes(StandardCharsets.UTF_8),"{\"x\":1.1}".getBytes(StandardCharsets.UTF_8),new byte[]{(byte)0xff},"{\"x\":\"\\uD800\"}".getBytes(StandardCharsets.UTF_8))){try{Json.object(bytes);}catch(IllegalArgumentException e){continue;}throw new AssertionError("invalid JSON accepted");}eq(Json.object("{\"x\":\"हिंदी\",\"v\":[true,null,10]}".getBytes(StandardCharsets.UTF_8)).get("x"),"हिंदी");});
            check("account credential projection excludes hashes and roles cannot be assigned in registration",()->{String text=Json.encode(w.account(owner));eq(text.contains("\"credential\":"),false);eq(w.account(owner).get("role"),"CUSTOMER");Map<String,Object> injected=new LinkedHashMap<>(accountBody);injected.put("role","ADMIN");fail(400,"UNEXPECTED_FIELDS",()->w.register(injected));});
            check("salted passwords use distinct verifiers and reject wrong values",()->{String pass=password();var a=Crypto.password(pass);var b=Crypto.password(pass);eq(a.get("iterations"),600000);eq(a.equals(b),false);eq(Crypto.verifies(pass,a),true);eq(Crypto.verifies("wrong",a),false);});
            check("short credentials cannot register",()->fail(400,"INVALID_PASSWORD",()->w.register(body("username","weak_user","display_name","Weak","password","short"))));
            check("new case retains unknown values without implicit zeros",()->{String id=create(w,owner);var row=w.readCase(owner,id);eq(Json.map(row.get("inputs")).size(),4);for(Object v:Json.map(row.get("inputs")).values())eq(v,Map.of("state","UNKNOWN"));eq(row.get("filing_available"),false);});
            check("customer preparer and admin cannot read another private case",()->{String id=create(w,owner);for(String actor:List.of(other,preparer,admin))fail(404,"CASE_NOT_FOUND",()->w.readCase(actor,id));eq(w.cases(admin).size(),0);});
            check("case creation replays without duplicating and changed body conflicts",()->{Map<String,Object> request=body("title","Once","request_id",Workspace.id());var first=w.createCase(owner,request);int count=w.cases(owner).size();eq(w.createCase(owner,request).get("status"),"REPLAYED");eq(w.cases(owner).size(),count);request.put("title","Different");fail(409,"IDEMPOTENCY_CONFLICT",()->w.createCase(owner,request));eq(first.get("status"),"APPLIED");});
            check("stale edit and edit-revert ABA cannot overwrite new snapshot",()->{String id=create(w,owner);var old=w.readCase(owner,id);var stale=cmd(old,"PROPOSE","field","SALARY","text","2 lakh","unit","");edit(w,owner,id,"PROPOSE","field","SALARY","text","1 lakh","unit","");edit(w,owner,id,"CLEAR","field","SALARY");fail(409,"STALE_CASE",()->w.edit(owner,id,stale));eq(w.readCase(owner,id).get("snapshot").equals(old.get("snapshot")),false);});
            check("explicit zero is estimated then requires exact separate confirmation",()->{String id=create(w,owner);edit(w,owner,id,"PROPOSE","field","SALARY","text","0 rupees","unit","");eq(Json.map(Json.map(w.readCase(owner,id).get("inputs")).get("SALARY")).get("state"),"ESTIMATED");fail(409,"DISPLAYED_AMOUNT_CHANGED",()->edit(w,owner,id,"CONFIRM","field","SALARY","amount","1.00"));edit(w,owner,id,"CONFIRM","field","SALARY","amount","0.00");eq(Json.map(Json.map(w.readCase(owner,id).get("inputs")).get("SALARY")).get("state"),"CONFIRMED");});
            check("income review prerequisites and later edits reset checkpoints",()->{String id=create(w,owner);fail(409,"CONFIRM_INCOME_FIRST",()->edit(w,owner,id,"REVIEW","inventory","INCOME"));for(String field:List.of("SALARY","SAVINGS_INTEREST","DEPOSIT_INTEREST","OTHER_INTEREST")){edit(w,owner,id,"PROPOSE","field",field,"text","0 rupees","unit","");edit(w,owner,id,"CONFIRM","field",field,"amount","0.00");}for(String inv:List.of("INCOME","NEW_DEDUCTIONS","OLD_DEDUCTIONS"))edit(w,owner,id,"REVIEW","inventory",inv);edit(w,owner,id,"PROPOSE","field","SALARY","text","1 lakh","unit","");eq(Json.map(w.readCase(owner,id).get("reviews")).values().stream().allMatch(v->v.equals(false)),true);});
            check("accepted retry preserves later saved value and current revision",()->{String id=create(w,owner);var request=cmd(w.readCase(owner,id),"PROPOSE","field","SALARY","text","1 lakh","unit","");w.edit(owner,id,request);edit(w,owner,id,"PROPOSE","field","SALARY","text","2 lakh","unit","");var current=w.readCase(owner,id);eq(w.edit(owner,id,request).get("status"),"REPLAYED");eq(w.readCase(owner,id),current);});
            check("forged authority fields and cross-route IDs cannot upgrade capabilities",()->{String id=create(w,owner);Map<String,Object> request=cmd(w.readCase(owner,id),"CLEAR","field","SALARY");request.put("rule_state","APPROVED");fail(400,"UNEXPECTED_FIELDS",()->w.edit(owner,id,request));fail(403,"ROLE_REQUIRED",()->w.publishPrice(owner,price("GUIDED_PREPARATION",time.instant().plusSeconds(60).toString(),100L)));});
            check("specific consent grants read-only preparation access and notes are snapshot-bound",()->{String id=create(w,owner);var request=body("request_id",Workspace.id(),"expected_revision",w.readCase(owner,id).get("revision"),"preparer_username","team_staff","expires_days",7L,"consent",false);fail(400,"EXPLICIT_CASE_SHARING_CONSENT_REQUIRED",()->w.grant(owner,id,request));request.put("consent",true);w.grant(owner,id,request);eq(w.readCase(preparer,id).get("review_only"),true);fail(404,"CASE_NOT_FOUND",()->edit(w,preparer,id,"PROPOSE","field","SALARY","text","1 lakh","unit",""));w.note(preparer,id,body("request_id",Workspace.id(),"expected_revision",w.readCase(preparer,id).get("revision"),"text","Check the sample bank interest."));eq(Json.map(Json.list(w.readCase(owner,id).get("preparation_notes")).get(0)).get("scope"),"PREPARATION_COMMENT_NOT_CA_SIGNOFF");});
            check("revocation immediately denies reads and prior note retries",()->{String id=create(w,owner);w.grant(owner,id,body("request_id",Workspace.id(),"expected_revision",w.readCase(owner,id).get("revision"),"preparer_username","team_staff","expires_days",1L,"consent",true));var note=body("request_id",Workspace.id(),"expected_revision",w.readCase(preparer,id).get("revision"),"text","Review item");w.note(preparer,id,note);String grant=(String)w.grants(owner,id).get(0).get("id");w.revoke(owner,id,body("request_id",Workspace.id(),"expected_revision",w.readCase(owner,id).get("revision"),"grant_id",grant));fail(404,"CASE_NOT_FOUND",()->w.readCase(preparer,id));fail(404,"CASE_NOT_FOUND",()->w.note(preparer,id,note));});
            check("expired grants are denied without user action",()->{String id=create(w,owner);w.grant(owner,id,body("request_id",Workspace.id(),"expected_revision",w.readCase(owner,id).get("revision"),"preparer_username","team_staff","expires_days",1L,"consent",true));time.current=time.current.plus(Duration.ofDays(1));fail(404,"CASE_NOT_FOUND",()->w.readCase(preparer,id));});
            check("future immutable prices and frozen quotes survive later price publication",()->{var first=price("GUIDED_PREPARATION",time.instant().plusSeconds(10).toString(),12500L);w.publishPrice(admin,first);eq(w.publishPrice(admin,first).get("status"),"REPLAYED");var request=body("request_id",Workspace.id(),"plan","GUIDED_PREPARATION");fail(409,"NO_ACTIVE_PRICE",()->w.quote(owner,request));time.current=time.current.plusSeconds(10);w.quote(owner,request);eq(w.quote(owner,request).get("status"),"REPLAYED");var quote=w.quotes(owner).get(0);w.publishPrice(admin,price("GUIDED_PREPARATION",time.instant().plusSeconds(10).toString(),25000L));time.current=time.current.plusSeconds(10);eq(w.quotes(owner).get(0),quote);eq(quote.get("amount_paise"),12500L);eq(quote.get("payment_available"),false);});
            check("support requests isolate customers and permit scoped admin responses",()->{var request=body("request_id",Workspace.id(),"topic","PRODUCT_HELP","subject","Sample support","message","How to confirm a value?");String ticket=(String)w.openTicket(owner,request).get("id");eq(w.openTicket(owner,request).get("status"),"REPLAYED");eq(w.tickets(other).size(),0);fail(404,"TICKET_NOT_FOUND",()->w.updateTicket(other,ticket,body("request_id",Workspace.id(),"expected_revision",1L,"status","RESOLVED","message","")));w.updateTicket(admin,ticket,body("request_id",Workspace.id(),"expected_revision",1L,"status","RESOLVED","message","Use the separate confirmation action."));eq(w.tickets(owner).get(0).get("status"),"RESOLVED");});
            check("archive prevents edits while deletion cannot resurrect an old create retry",()->{var request=body("title","Delete me","request_id",Workspace.id());String id=(String)w.createCase(owner,request).get("id");edit(w,owner,id,"ARCHIVE");fail(409,"CASE_ARCHIVED",()->edit(w,owner,id,"CLEAR","field","SALARY"));edit(w,owner,id,"RESTORE");w.deleteCase(owner,id,body("expected_revision",w.readCase(owner,id).get("revision"),"confirm","DELETE"));eq(w.createCase(owner,request).get("status"),"REPLAYED");fail(404,"CASE_NOT_FOUND",()->w.readCase(owner,id));});
            check("local store failure before commit does not publish partial state",()->{fail(503,"STORAGE_WRITE_FAILED",()->vault.transaction(state->{state.put("oversized","x".repeat(8_388_609));return null;}));eq(vault.read(state->state.containsKey("oversized")),false);});
            check("second local writer is refused rather than corrupting shared state",()->{try(VaultStore ignored=new VaultStore(records,key)){ignored.read(s->s.size());throw new AssertionError("second writer opened");}catch(java.io.IOException expected){eq(expected.getMessage(),"workspace already open");}});
            check("audit contains no salary text password source content or note bodies",()->{String audit=Json.encode(w.audit(admin));for(String secret:List.of("1 lakh","200000.00","Sample support","Review item","credential","password","gross_amount"))eq(audit.contains(secret),false);});
            check("generated owner isolation covers all private resource operations",()->{String id=create(w,owner);for(String actor:List.of(other,preparer,admin)){fail(404,"CASE_NOT_FOUND",()->w.readCase(actor,id));fail(404,"CASE_NOT_FOUND",()->w.exportCase(actor,id));fail(404,"CASE_NOT_FOUND",()->w.comparison(actor,id));fail(404,"CASE_NOT_FOUND",()->w.grants(actor,id));generated+=4;}});
        }
        check("saved accounts and cases survive a real close and reopen",()->{try(VaultStore vault=new VaultStore(records,key)){Workspace w=new Workspace(vault,time);eq(w.login(body("username",accountBody.get("username"),"password",accountBody.get("password"))).get("id"),owner);eq(w.cases(owner).isEmpty(),false);eq(new String(Files.readAllBytes(records.resolve("workspace.vault")),StandardCharsets.ISO_8859_1).contains((String)accountBody.get("password")),false);}});
        check("encrypted store tampering fails closed",()->{Path corrupt=folder.resolve("corrupt");Files.createDirectory(corrupt);byte[] bytes=Files.readAllBytes(records.resolve("workspace.vault"));bytes[bytes.length-1]^=1;Files.write(corrupt.resolve("workspace.vault"),bytes);try(VaultStore ignored=new VaultStore(corrupt,key)){ignored.read(s->s.size());throw new AssertionError("corrupt store accepted");}catch(javax.crypto.AEADBadTagException expected){/* authentic rejection */}});
        check("missing key cannot silently recreate an existing data store",()->{try(VaultStore ignored=new VaultStore(records,folder.resolve("missing/key"))){ignored.read(s->s.size());throw new AssertionError("key recreated");}catch(java.io.IOException expected){eq(expected.getMessage(),"vault key unavailable");}});
        check("public proxy origin canonicalizes HTTPS authority",()->{eq(PublicEndpoint.https("https://TAX.EXAMPLE.IN:443/").origin(),"https://tax.example.in");eq(PublicEndpoint.https("https://tax.example.in:9443").authority(),"tax.example.in:9443");});
        check("public proxy origin rejects HTTP credentials paths queries and fragments",()->{for(String value:List.of("http://tax.example.in","https://user:secret@tax.example.in","https://tax.example.in/path","https://tax.example.in/?debug=true","https://tax.example.in/#fragment","https://tax.example.in:0","https://tax.example.in:65536","https://bad_host")){try{PublicEndpoint.https(value);}catch(IllegalArgumentException expected){continue;}throw new AssertionError("unsafe public origin accepted");}});
        System.out.println(Json.encode(Map.of("startup_unit_groups",passed,"generated_owner_isolation_checks",generated,"mysql_tested",false,"tax_validated",false)));
    }
}
